rss.channel:
  Clementine
  https://www.clementine-player.org/
  Clementine Player
  en
{#
  The MacUpdate entities Clementine's tools/mac-update publishes. This
  template is autoescaped, so the notes' HTML goes into  as
  escaped text, which Sparkle reads back as HTML.
#}
{% for update in updates %}


    Clementine {{ update.version }}
    {{ update.published|rfc2822 }}
    {# The app's CFBundleVersion, which Sparkle compares. #}
    {{ update.build }}
    {{ update.version }}
    {{ update.min_macos }}
    {{ update.notes_html }}


{% endfor %}
